import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    idx = 2
    atk = []
    defs = []
    for _ in range(n):
        pos = data[idx]
        s = int(data[idx + 1])
        idx += 2
        if pos == "ATK":
            atk.append(s)
        else:
            defs.append(s)
    ciel = [int(data[idx + i]) for i in range(m)]

    atk_sorted = sorted(atk)
    ciel_sorted = sorted(ciel)

    # Strategy 1: only attack ATK cards, ignore DEF
    la = len(atk_sorted)
    lc = len(ciel_sorted)
    dp = [[0] * (lc + 1) for _ in range(la + 1)]
    for i in range(1, la + 1):
        for j in range(1, lc + 1):
            best = max(dp[i - 1][j], dp[i][j - 1])
            if ciel_sorted[j - 1] >= atk_sorted[i - 1]:
                v = dp[i - 1][j - 1] + ciel_sorted[j - 1] - atk_sorted[i - 1]
                if v > best:
                    best = v
            dp[i][j] = best
    ans = dp[la][lc]

    # Strategy 2: destroy all Jiro cards, then hit directly with remaining
    def_sorted = sorted(defs, reverse=True)
    atk_desc = sorted(atk, reverse=True)
    remaining = sorted(ciel)
    possible = True

    for d in def_sorted:
        found = -1
        for i, c in enumerate(remaining):
            if c > d:
                found = i
                break
        if found == -1:
            possible = False
            break
        remaining.pop(found)

    if possible:
        for a in atk_desc:
            found = -1
            for i, c in enumerate(remaining):
                if c >= a:
                    found = i
                    break
            if found == -1:
                possible = False
                break
            remaining.pop(found)

    if possible:
        total = sum(remaining)
        for a in atk:
            total -= a
        if total > ans:
            ans = total

    print(ans)

if __name__ == "__main__":
    solve()
